import React, { useState } from "react";
import ReactDOM from "react-dom/client";

function App() {
  const [showCropForm, setShowCropForm] = useState(false);
  const [showExpenseForm, setShowExpenseForm] = useState(false);
  const [showIncomeForm, setShowIncomeForm] = useState(false);

  // Crop
  const [cropName, setCropName] = useState("");
  const [area, setArea] = useState("");
  const [expense, setExpense] = useState("");
  const [income, setIncome] = useState("");

  // Expense
  const [expenseCrop, setExpenseCrop] = useState("");
  const [expenseCategory, setExpenseCategory] = useState("");
  const [expenseAmount, setExpenseAmount] = useState("");
  const [expenseDescription, setExpenseDescription] = useState("");

  // Income
  const [incomeCrop, setIncomeCrop] = useState("");
  const [quantity, setQuantity] = useState("");
  const [unit, setUnit] = useState("Quintal");
  const [sellingPrice, setSellingPrice] = useState("");
  const [incomeDescription, setIncomeDescription] = useState("");

  const [crops, setCrops] = useState([
    {
      name: "Wheat",
      area: 3,
      expense: 15000,
      income: 28000,
    },
    {
      name: "Soybean",
      area: 2,
      expense: 12000,
      income: 24000,
    },
  ]);

  const [expenses, setExpenses] = useState([]);
  const [incomes, setIncomes] = useState([]);

  const totalExpense = crops.reduce(
    (total, crop) => total + crop.expense,
    0
  );

  const totalIncome = crops.reduce(
    (total, crop) => total + crop.income,
    0
  );

  const totalProfit = totalIncome - totalExpense;

  // ADD CROP
  const addCrop = (e) => {
    e.preventDefault();

    if (!cropName || !area || !expense || !income) {
      alert("Please fill all crop fields.");
      return;
    }

    const newCrop = {
      name: cropName,
      area: Number(area),
      expense: Number(expense),
      income: Number(income),
    };

    setCrops([...crops, newCrop]);

    setCropName("");
    setArea("");
    setExpense("");
    setIncome("");
    setShowCropForm(false);
  };

  // ADD EXPENSE
  const addExpense = (e) => {
    e.preventDefault();

    if (!expenseCrop || !expenseCategory || !expenseAmount) {
      alert("Please fill all expense fields.");
      return;
    }

    const amount = Number(expenseAmount);

    const newExpense = {
      crop: expenseCrop,
      category: expenseCategory,
      amount: amount,
      description: expenseDescription,
    };

    setExpenses([...expenses, newExpense]);

    setCrops(
      crops.map((crop) =>
        crop.name === expenseCrop
          ? {
              ...crop,
              expense: crop.expense + amount,
            }
          : crop
      )
    );

    setExpenseCrop("");
    setExpenseCategory("");
    setExpenseAmount("");
    setExpenseDescription("");
    setShowExpenseForm(false);
  };

  // ADD INCOME
  const addIncome = (e) => {
    e.preventDefault();

    if (!incomeCrop || !quantity || !sellingPrice) {
      alert("Please fill all income fields.");
      return;
    }

    const totalAmount =
      Number(quantity) * Number(sellingPrice);

    const newIncome = {
      crop: incomeCrop,
      quantity: Number(quantity),
      unit: unit,
      sellingPrice: Number(sellingPrice),
      amount: totalAmount,
      description: incomeDescription,
    };

    setIncomes([...incomes, newIncome]);

    setCrops(
      crops.map((crop) =>
        crop.name === incomeCrop
          ? {
              ...crop,
              income: crop.income + totalAmount,
            }
          : crop
      )
    );

    setIncomeCrop("");
    setQuantity("");
    setUnit("Quintal");
    setSellingPrice("");
    setIncomeDescription("");
    setShowIncomeForm(false);
  };

  return (
    <div style={pageStyle}>

      {/* HEADER */}
      <header style={headerStyle}>
        <div>
          <h1 style={{ margin: 0 }}>🌾 Kisan Profit</h1>
          <small>Smart Farming • Better Profit</small>
        </div>

        <div>👨‍🌾 Farmer Dashboard</div>
      </header>

      <main style={mainStyle}>

        {/* WELCOME */}
        <section>
          <h2 style={welcomeStyle}>
            Welcome to Kisan Profit 👋
          </h2>

          <p style={subtitleStyle}>
            Track your crops, expenses, income and
            actual farming profit.
          </p>
        </section>

        {/* SUMMARY */}
        <section style={cardsGrid}>

          <div style={cardStyle}>
            <div style={iconStyle}>🌱</div>
            <p>Total Crops</p>
            <h2>{crops.length}</h2>
          </div>

          <div style={cardStyle}>
            <div style={iconStyle}>💸</div>
            <p>Total Expense</p>
            <h2>
              ₹{totalExpense.toLocaleString()}
            </h2>
          </div>

          <div style={cardStyle}>
            <div style={iconStyle}>💰</div>
            <p>Total Income</p>
            <h2>
              ₹{totalIncome.toLocaleString()}
            </h2>
          </div>

          <div
            style={{
              ...cardStyle,
              borderLeft: "5px solid #176b36",
            }}
          >
            <div style={iconStyle}>📈</div>
            <p>Net Profit</p>

            <h2
              style={{
                color:
                  totalProfit >= 0
                    ? "#176b36"
                    : "#d32f2f",
              }}
            >
              ₹{totalProfit.toLocaleString()}
            </h2>
          </div>

        </section>

        {/* BUTTONS */}
        <section style={buttonSection}>

          <button
            onClick={() => {
              setShowCropForm(true);
              setShowExpenseForm(false);
              setShowIncomeForm(false);
            }}
            style={greenButton}
          >
            + Add Crop
          </button>

          <button
            onClick={() => {
              setShowExpenseForm(true);
              setShowCropForm(false);
              setShowIncomeForm(false);
            }}
            style={outlineButton}
          >
            + Add Expense
          </button>

          <button
            onClick={() => {
              setShowIncomeForm(true);
              setShowCropForm(false);
              setShowExpenseForm(false);
            }}
            style={outlineButton}
          >
            + Add Income
          </button>

        </section>

        {/* ADD CROP */}
        {showCropForm && (
          <section style={formBox}>
            <h2>🌱 Add New Crop</h2>

            <form onSubmit={addCrop}>
              <div style={formGrid}>

                <FormInput
                  label="Crop Name"
                  placeholder="e.g. Cotton"
                  value={cropName}
                  onChange={setCropName}
                />

                <FormInput
                  label="Area (Acres)"
                  placeholder="e.g. 5"
                  type="number"
                  value={area}
                  onChange={setArea}
                />

                <FormInput
                  label="Total Expense (₹)"
                  placeholder="e.g. 20000"
                  type="number"
                  value={expense}
                  onChange={setExpense}
                />

                <FormInput
                  label="Total Income (₹)"
                  placeholder="e.g. 35000"
                  type="number"
                  value={income}
                  onChange={setIncome}
                />

              </div>

              <div style={buttonRow}>
                <button
                  type="submit"
                  style={greenButton}
                >
                  Save Crop
                </button>

                <button
                  type="button"
                  onClick={() => setShowCropForm(false)}
                  style={cancelButton}
                >
                  Cancel
                </button>
              </div>
            </form>
          </section>
        )}

        {/* ADD EXPENSE */}
        {showExpenseForm && (
          <section style={formBox}>
            <h2>💸 Add Farming Expense</h2>

            <form onSubmit={addExpense}>

              <div style={formGrid}>

                <div>
                  <label>Select Crop</label>

                  <select
                    value={expenseCrop}
                    onChange={(e) =>
                      setExpenseCrop(e.target.value)
                    }
                    style={inputStyle}
                  >
                    <option value="">
                      Select Crop
                    </option>

                    {crops.map((crop, index) => (
                      <option
                        key={index}
                        value={crop.name}
                      >
                        {crop.name}
                      </option>
                    ))}
                  </select>
                </div>

                <div>
                  <label>Expense Category</label>

                  <select
                    value={expenseCategory}
                    onChange={(e) =>
                      setExpenseCategory(e.target.value)
                    }
                    style={inputStyle}
                  >
                    <option value="">
                      Select Category
                    </option>
                    <option>Seeds</option>
                    <option>Fertilizer</option>
                    <option>Pesticides</option>
                    <option>Labour</option>
                    <option>Irrigation</option>
                    <option>Machinery</option>
                    <option>Transport</option>
                    <option>Other</option>
                  </select>
                </div>

                <FormInput
                  label="Amount (₹)"
                  placeholder="e.g. 5000"
                  type="number"
                  value={expenseAmount}
                  onChange={setExpenseAmount}
                />

                <FormInput
                  label="Description"
                  placeholder="e.g. Urea fertilizer"
                  value={expenseDescription}
                  onChange={setExpenseDescription}
                />

              </div>

              <div style={buttonRow}>
                <button
                  type="submit"
                  style={greenButton}
                >
                  Save Expense
                </button>

                <button
                  type="button"
                  onClick={() =>
                    setShowExpenseForm(false)
                  }
                  style={cancelButton}
                >
                  Cancel
                </button>
              </div>

            </form>
          </section>
        )}

        {/* ADD INCOME */}
        {showIncomeForm && (
          <section style={formBox}>

            <h2 style={{ color: "#174d2a" }}>
              💰 Add Crop Income
            </h2>

            <form onSubmit={addIncome}>

              <div style={formGrid}>

                {/* CROP */}
                <div>
                  <label>Select Crop</label>

                  <select
                    value={incomeCrop}
                    onChange={(e) =>
                      setIncomeCrop(e.target.value)
                    }
                    style={inputStyle}
                  >
                    <option value="">
                      Select Crop
                    </option>

                    {crops.map((crop, index) => (
                      <option
                        key={index}
                        value={crop.name}
                      >
                        {crop.name}
                      </option>
                    ))}
                  </select>
                </div>

                {/* QUANTITY */}
                <FormInput
                  label="Quantity Produced"
                  placeholder="e.g. 20"
                  type="number"
                  value={quantity}
                  onChange={setQuantity}
                />

                {/* UNIT */}
                <div>
                  <label>Unit</label>

                  <select
                    value={unit}
                    onChange={(e) =>
                      setUnit(e.target.value)
                    }
                    style={inputStyle}
                  >
                    <option value="Kg">Kg</option>
                    <option value="Quintal">
                      Quintal
                    </option>
                    <option value="Ton">Ton</option>
                  </select>
                </div>

                {/* SELLING PRICE */}
                <FormInput
                  label="Selling Price / Unit (₹)"
                  placeholder="e.g. 2500"
                  type="number"
                  value={sellingPrice}
                  onChange={setSellingPrice}
                />

                {/* DESCRIPTION */}
                <FormInput
                  label="Description"
                  placeholder="e.g. Sold at local market"
                  value={incomeDescription}
                  onChange={setIncomeDescription}
                />

              </div>

              {/* AUTO CALCULATION */}
              {quantity && sellingPrice && (
                <div
                  style={{
                    marginTop: "25px",
                    padding: "18px",
                    backgroundColor: "#edf5ee",
                    borderRadius: "10px",
                  }}
                >
                  <strong>
                    Calculated Income:
                  </strong>

                  <span
                    style={{
                      marginLeft: "15px",
                      color: "#176b36",
                      fontSize: "22px",
                      fontWeight: "bold",
                    }}
                  >
                    ₹
                    {(
                      Number(quantity) *
                      Number(sellingPrice)
                    ).toLocaleString()}
                  </span>
                </div>
              )}

              <div style={buttonRow}>

                <button
                  type="submit"
                  style={greenButton}
                >
                  Save Income
                </button>

                <button
                  type="button"
                  onClick={() =>
                    setShowIncomeForm(false)
                  }
                  style={cancelButton}
                >
                  Cancel
                </button>

              </div>

            </form>
          </section>
        )}

        {/* EXPENSE HISTORY */}
        {expenses.length > 0 && (
          <section style={tableBox}>

            <h2>💸 Expense History</h2>

            <table style={tableStyle}>

              <thead>
                <tr style={tableHeader}>
                  <th style={cellStyle}>Crop</th>
                  <th style={cellStyle}>Category</th>
                  <th style={cellStyle}>Amount</th>
                  <th style={cellStyle}>
                    Description
                  </th>
                </tr>
              </thead>

              <tbody>
                {expenses.map((item, index) => (
                  <tr key={index}>

                    <td style={cellStyle}>
                      {item.crop}
                    </td>

                    <td style={cellStyle}>
                      {item.category}
                    </td>

                    <td style={cellStyle}>
                      ₹
                      {item.amount.toLocaleString()}
                    </td>

                    <td style={cellStyle}>
                      {item.description || "-"}
                    </td>

                  </tr>
                ))}
              </tbody>

            </table>
          </section>
        )}

        {/* INCOME HISTORY */}
        {incomes.length > 0 && (
          <section style={tableBox}>

            <h2>💰 Income History</h2>

            <table style={tableStyle}>

              <thead>
                <tr style={tableHeader}>
                  <th style={cellStyle}>Crop</th>
                  <th style={cellStyle}>
                    Quantity
                  </th>
                  <th style={cellStyle}>
                    Selling Price
                  </th>
                  <th style={cellStyle}>
                    Total Income
                  </th>
                  <th style={cellStyle}>
                    Description
                  </th>
                </tr>
              </thead>

              <tbody>
                {incomes.map((item, index) => (
                  <tr key={index}>

                    <td style={cellStyle}>
                      {item.crop}
                    </td>

                    <td style={cellStyle}>
                      {item.quantity} {item.unit}
                    </td>

                    <td style={cellStyle}>
                      ₹
                      {item.sellingPrice.toLocaleString()}
                    </td>

                    <td
                      style={{
                        ...cellStyle,
                        color: "#176b36",
                        fontWeight: "bold",
                      }}
                    >
                      ₹{item.amount.toLocaleString()}
                    </td>

                    <td style={cellStyle}>
                      {item.description || "-"}
                    </td>

                  </tr>
                ))}
              </tbody>

            </table>
          </section>
        )}

        {/* PROFIT ANALYSIS */}
        <section style={tableBox}>

          <h2>📊 Crop Profit Analysis</h2>

          <table style={tableStyle}>

            <thead>
              <tr style={tableHeader}>
                <th style={cellStyle}>Crop</th>
                <th style={cellStyle}>Area</th>
                <th style={cellStyle}>Expense</th>
                <th style={cellStyle}>Income</th>
                <th style={cellStyle}>
                  Profit/Loss
                </th>
              </tr>
            </thead>

            <tbody>
              {crops.map((crop, index) => {

                const profit =
                  crop.income - crop.expense;

                return (
                  <tr key={index}>

                    <td style={cellStyle}>
                      {crop.name}
                    </td>

                    <td style={cellStyle}>
                      {crop.area} acres
                    </td>

                    <td style={cellStyle}>
                      ₹
                      {crop.expense.toLocaleString()}
                    </td>

                    <td style={cellStyle}>
                      ₹
                      {crop.income.toLocaleString()}
                    </td>

                    <td
                      style={{
                        ...cellStyle,
                        color:
                          profit >= 0
                            ? "#176b36"
                            : "#d32f2f",
                        fontWeight: "bold",
                      }}
                    >
                      {profit >= 0 ? "+" : "-"}₹
                      {Math.abs(
                        profit
                      ).toLocaleString()}
                    </td>

                  </tr>
                );
              })}
            </tbody>

          </table>
        </section>

      </main>
    </div>
  );
}

/* FORM INPUT COMPONENT */

function FormInput({
  label,
  placeholder,
  type = "text",
  value,
  onChange,
}) {
  return (
    <div>
      <label>{label}</label>

      <input
        type={type}
        placeholder={placeholder}
        value={value}
        onChange={(e) =>
          onChange(e.target.value)
        }
        style={inputStyle}
      />
    </div>
  );
}

